<script setup>
import { ref, watch } from 'vue'
import { getWeatherForecast } from '@/api/weather'

const props = defineProps({ plotId: { type: String, default: '' }, compact: Boolean })
const weather = ref(null)
const loading = ref(false)
async function load() { if (!props.plotId) return; loading.value = true; try { weather.value = await getWeatherForecast(props.plotId) } catch { weather.value = { available: false, message: '天气数据暂不可用' } } finally { loading.value = false } }
watch(() => props.plotId, load, { immediate: true })
</script>
<template><section v-loading="loading" :class="['weather-overview', { compact }]"><template v-if="weather?.available"><div v-if="!compact" class="weather-icon">☀</div><div class="weather-copy"><span v-if="!compact">奉节橙园天气</span><strong>{{ weather.currentTemperature }}℃ <em>{{ weather.weather }}</em></strong><small>{{ weather.location }} · 降雨概率 {{ weather.rainProbability24h }}% · 预计降雨 {{ weather.rainfall24h }}mm</small></div><el-tag v-if="!compact" type="warning" effect="plain">{{ weather.source === 'mock' ? '模拟天气' : '实时天气' }}</el-tag></template><template v-else><div v-if="!compact" class="weather-icon muted">!</div><div class="weather-copy"><span v-if="!compact">天气服务</span><strong>暂不可用</strong><small>{{ weather?.message || '农田监测和农事任务不受影响' }}</small></div></template></section></template>
<style scoped>.weather-overview{min-height:88px;display:flex;align-items:center;gap:16px;margin-bottom:18px;padding:18px 22px;border:1px solid #f0d9c5;border-radius:18px;background:linear-gradient(120deg,#fff8ed,#fffdfa);box-shadow:0 8px 24px rgba(112,58,23,.06)}.weather-overview.compact{min-width:390px;min-height:74px;justify-content:flex-end;margin:0;padding:10px 0;border:0;border-radius:0;background:transparent;box-shadow:none}.weather-icon{width:48px;height:48px;display:grid;place-items:center;border-radius:15px;color:#c75e14;background:#ffe8c8;font-size:25px}.weather-icon.muted{color:#8a7769;background:#eee9e4}.weather-copy{min-width:0;display:flex;flex:1;flex-direction:column;gap:4px}.weather-overview span,.weather-overview small{color:#92705a;font-size:12px}.weather-overview strong{color:#542c13;font-size:18px}.compact .weather-copy{flex:0 1 auto;align-items:flex-end;text-align:right}.compact strong{color:rgba(84,44,19,.76);font-size:30px;font-weight:350;line-height:1.15;letter-spacing:.3px;text-shadow:0 1px 0 rgba(255,255,255,.72)}.weather-overview strong em{margin-left:8px;font-size:13px;font-style:normal;font-weight:400}.compact strong em{color:rgba(84,44,19,.62);font-weight:300}.compact small{color:rgba(122,82,55,.58);font-weight:300;letter-spacing:.15px;white-space:nowrap}@media(max-width:1100px){.weather-overview.compact{width:100%;min-width:0;justify-content:flex-end;padding-right:0}.compact small{white-space:normal}}</style>
